import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static final long INF = 1L << 60;
    static long[] mn, cn, lz;
    static long bestMin, bestCnt;

    static void pull(int node) {
        int left = 2 * node, right = left + 1;
        if (mn[left] < mn[right]) {
            mn[node] = mn[left];
            cn[node] = cn[left];
        } else if (mn[left] > mn[right]) {
            mn[node] = mn[right];
            cn[node] = cn[right];
        } else {
            mn[node] = mn[left];
            cn[node] = cn[left] + cn[right];
        }
    }

    static void build(int node, int l, int r, long[] a) {
        if (l == r) {
            mn[node] = a[l];
            cn[node] = 1;
            return;
        }
        int mid = (l + r) / 2;
        build(2 * node, l, mid, a);
        build(2 * node + 1, mid + 1, r, a);
        pull(node);
    }

    static void bump(int node, long d) {
        mn[node] += d;
        lz[node] += d;
    }

    static void push(int node) {
        if (lz[node] != 0) {
            bump(2 * node, lz[node]);
            bump(2 * node + 1, lz[node]);
            lz[node] = 0;
        }
    }

    static void add(int node, int l, int r, int ql, int qr, long d) {
        if (ql <= l && r <= qr) {
            bump(node, d);
            return;
        }
        push(node);
        int mid = (l + r) / 2;
        if (ql <= mid) add(2 * node, l, mid, ql, qr, d);
        if (qr > mid) add(2 * node + 1, mid + 1, r, ql, qr, d);
        pull(node);
    }

    static void ask(int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) {
            if (mn[node] < bestMin) {
                bestMin = mn[node];
                bestCnt = cn[node];
            } else if (mn[node] == bestMin) {
                bestCnt += cn[node];
            }
            return;
        }
        push(node);
        int mid = (l + r) / 2;
        if (ql <= mid) ask(2 * node, l, mid, ql, qr);
        if (qr > mid) ask(2 * node + 1, mid + 1, r, ql, qr);
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[][] ops = new long[(int) q][4];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = Long.parseLong(next());
            }
        }

        int cn2 = (int) n;
        mn = new long[4 * cn2];
        cn = new long[4 * cn2];
        lz = new long[4 * cn2];
        build(1, 0, cn2 - 1, a);
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < q; k++) {
            long kind = ops[k][0];
            int l = (int) ops[k][1], rr = (int) ops[k][2];
            long x = ops[k][3];
            if (kind == 1) {
                add(1, 0, cn2 - 1, l - 1, rr - 1, x);
            } else {
                bestMin = INF;
                bestCnt = 0;
                ask(1, 0, cn2 - 1, l - 1, rr - 1);
                if (out.length() > 0) out.append(" ");
                out.append(bestMin).append(" ").append(bestCnt);
            }
        }
        System.out.println(out);
    }
}
